def parse(rows):
    result={}
    for key,raw in rows.items():
        questions=[]
        for line in raw.strip().splitlines():
            bits=[part.strip() for part in line.split("|")]
            if len(bits)!=6: raise ValueError((key,line,len(bits)))
            prompt,yes,no1,no2,feedback,source=bits
            if len({yes,no1,no2})!=3: raise ValueError((key,prompt))
            questions.append(dict(question=prompt,options=[yes,no1,no2],feedback=feedback,source=int(source)))
        if len(questions)!=10:raise ValueError((key,len(questions)))
        result[key]=questions
    return result
